function canTurnInto(grid: number[][], target: number[][]): boolean {
  const n = grid.length;
  let cur = grid;
  for (let turn = 0; turn < 4; turn++) {
    if (cur.every((row, i) => row.every((v, j) => v === target[i][j]))) return true;
    const prev = cur;
    // new (i, j) takes old (n - 1 - j, i)
    cur = prev.map((_, i) => prev.map((_, j) => prev[n - 1 - j][i]));
  }
  return false;
}

