function canTurnInto(grid: number[][], target: number[][]): boolean {
  const n = grid.length;
  const ok = [true, true, true, true];
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const t = target[i][j];
      if (grid[i][j] !== t) ok[0] = false;
      if (grid[n - 1 - j][i] !== t) ok[1] = false;
      if (grid[n - 1 - i][n - 1 - j] !== t) ok[2] = false;
      if (grid[j][n - 1 - i] !== t) ok[3] = false;
    }
  }
  return ok.some(Boolean);
}

